test('add the exact available product', async ({ page }) => {
  // 1. Locate article cards
  // 2. Filter by exact Widget Pro heading and exact In Stock text
  // 3. Assert one card remains
  // 4. Click Add to Cart inside it
  // 5. Assert the status message
});

challenges.solution:
const card = page
  .getByRole('article')
  .filter({
    has: page.getByRole('heading', { name: 'Widget Pro', exact: true }),
  })
  .filter({ has: page.getByText('In Stock', { exact: true }) });

await expect(card).toHaveCount(1);
await card.getByRole('button', { name: 'Add to Cart' }).click();
await expect(page.getByRole('status')).toHaveText('Added Widget Pro!');

