import { test, expect } from '@playwright/test';

test('resubmit Order ORD-1042', async ({ page }) => {
  const order = page.getByRole('article').first();
  await order.getByRole('button', { name: 'Submit order' }).click();
  await page.waitForTimeout(1000);

  const status = await page.getByRole('status').first().textContent();
  expect(status).toBeTruthy();
});

challenges.solution:
const targetOrder = page.getByRole('article').filter({
  has: page.getByRole('heading', {
    name: 'Order ORD-1042',
    exact: true,
  }),
});

await expect(targetOrder).toHaveCount(1);
await targetOrder.getByRole('button', { name: 'Submit order' }).click();
await expect(targetOrder.getByRole('status')).toHaveText(
  'Order submitted: ORD-1042',
);
